PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT * {
   ?s ex:predicate ?o
   LATERAL {
      SELECT * { ?s ex:alternative ?alt }
   }
}

PREFIX ex: <http://example.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT * {
   ?s ex:predicate ?o
   LATERAL {
      {SELECT * { ?s rdfs:label ?label } ORDER BY ?label LIMIT 1}
      UNION
      {SELECT * { ?s ex:alternative ?alt } ORDER BY ?alt LIMIT 1}
   }
}

PREFIX ex: <http://example.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT * {
   ?s ex:predicate ?o
   LATERAL {
      SELECT * {
         ?s rdfs:label ?label
         FILTER(CONTAINS(STR(?label), "1"))
      } LIMIT 1
   }
}
